mapper.select:
SELECT GROUP_ID, OWNER_ID, STATUS
FROM GYE_GROUP
WHERE GROUP_ID = #{groupId}

SELECT GYE_MEMBER_ID, GROUP_ID, MEMBER_ID, STATUS, PAYOUT_RECEIVED_YN
FROM GYE_MEMBER
WHERE GROUP_ID = #{groupId}
  AND MEMBER_ID = #{memberId}

SELECT COUNT(*)
FROM WITHDRAWAL_REQUEST
WHERE GROUP_ID = #{groupId}
  AND MEMBER_ID = #{memberId}
  AND STATUS IN ('SETTLEMENT_PENDING', 'CONSENT_PENDING')

mapper.delete:
DELETE FROM CONSENT
WHERE CONSENT_TYPE = 'SETTLEMENT'
  AND TARGET_ID = #{withdrawalRequestId}

mapper.update:
UPDATE WITHDRAWAL_REQUEST
SET RECONFIRM_COUNT = RECONFIRM_COUNT + 1
WHERE WITHDRAWAL_REQUEST_ID = #{withdrawalRequestId}

mapper.select:
SELECT COUNT(*)
FROM GYE_MEMBER
WHERE GROUP_ID = #{groupId}
  AND STATUS = 'ACTIVE'
  AND MEMBER_ID != #{applicantId}

mapper.update:
UPDATE GYE_MEMBER
SET STATUS  = 'WITHDRAWN',
    LEFT_AT = SYSDATE
WHERE GROUP_ID = #{groupId}
  AND MEMBER_ID = #{memberId}

mapper.select:
SELECT MEMBER_ID
FROM GYE_MEMBER
WHERE GROUP_ID = #{groupId}
  AND STATUS = 'ACTIVE'
  AND MEMBER_ID != #{excludeMemberId}
